export interface MissingWorkingFolderResolution {
    kind: 'missing-working-folder'
    configuredWorkingFolder: string
    folders: TopLevelFolderReference[]
    project: ProjectReference
    resolvedWorkingFolder: string
    storageType: StorageType
}

export interface ProjectFolderSetupResolution {
    folders: TopLevelFolderReference[]
    kind: 'project-folder-setup'
    project: ProjectReference
    storageType: 'github' | 'local'
}

export type ProjectOpenResolution = MissingWorkingFolderResolution | ProjectFolderSetupResolution

export interface ProjectSessionState {
    errorMessage: string | null
    isCommitting: boolean
    isLoading: boolean
    isPulling: boolean
    isPushing: boolean
    pendingGithubConflictProject: ProjectReference | null
}

export interface CardCreationState {
    isCreatingCard: boolean
}

const EMPTY_TOP_LEVEL_FOLDERS: TopLevelFolderReference[] = []

function isMissingWorkingFolderError(error: unknown): error is { workingFolder: string } {
    if (!error || typeof error !== 'object') return false

    const storageError = error as { code?: unknown; workingFolder?: unknown }

    return storageError.code === MISSING_WORKING_FOLDER_ERROR && typeof storageError.workingFolder === 'string'
}

function createGithubStorage(accessToken: string | null, isReadOnly = false) {
    const storage = new GithubStorageService(isReadOnly)
    storage.init({ accessToken: accessToken ?? '' })

    return storage
}

async function persistWorkingFolder(storage: StorageService, project: ProjectReference, workingFolder: string) {
    const projectConfig = await storage.loadProjectConfig(project)
    configService.loadProjectConfig(projectConfig)
    let nextConfig = { ...configService.getProjectConfig(), workingFolder }
    if (projectConfig?.states === undefined) {
        const resolvedConfig = resolveProjectConfigPaths(nextConfig)
        const projectFiles = await storage.loadProjectRoot(project, resolvedConfig.workingFolder)
        const { activeCards } = markdownParsingService.splitCards(projectFiles.files, resolvedConfig.workingFolder)
        const derivedStates = deriveStatesFromCards(activeCards)
        nextConfig = { ...nextConfig, states: mergeStatesWithDefaults(derivedStates) }
    }
    configService.loadProjectConfig(nextConfig)
    await storage.saveProjectConfig(project, nextConfig)
}

function requireProjectFolder(projectFolder: string) {
    const normalizedFolder = projectFolder.trim().replace(/\\/gu, '/')
    if (normalizedFolder.length === 0) throw new Error('Project folder is required')
    if (normalizedFolder === '.' || normalizedFolder === '..' || normalizedFolder.includes('/')) {
        throw new Error('Project folder must be a root folder name')
    }

    return normalizedFolder
}

async function listTopLevelFolders(storage: StorageService, project: ProjectReference) {
    try {
        return await storage.listTopLevelFolders(project)
    } catch {
        return EMPTY_TOP_LEVEL_FOLDERS
    }
}

async function createMissingWorkingFolderResolution(
    storage: StorageService,
    storageType: StorageType,
    project: ProjectReference,
): Promise<MissingWorkingFolderResolution> {
    const config = configService.getProjectConfig()
    const resolvedConfig = resolveProjectConfigPaths(config)
    const folders = await listTopLevelFolders(storage, project)

    return {
        configuredWorkingFolder: config.workingFolder,
        folders,
        kind: 'missing-working-folder',
        project,
        resolvedWorkingFolder: resolvedConfig.workingFolder,
        storageType,
    }
}

async function loadProjectSession(
    storage: StorageService,
    storageType: StorageType,
    project: ProjectReference,
    onActivated: () => void,
) {
    try {
        await activateProjectSession(storage, storageType, project)
        onActivated()

        return null
    } catch (error) {
        if (!isMissingWorkingFolderError(error)) throw error

        return createMissingWorkingFolderResolution(storage, storageType, project)
    }
}

async function activateProjectSession(storage: StorageService, storageType: StorageType, project: ProjectReference) {
    await projectPersistenceService.flushPendingChanges()
    projectAccessService.setReadOnly(storageType === 'github-readonly')
    const activeStorage = await activateStorageService(storageType, storage)
    dataService.init({ storage: activeStorage })
    await dataService.projectLoading.openProject(project)
    remoteConnectionService.setProjectStorageActive(storageType === 'remote')
    writeLastProject(storageType, project)
}

async function resolveRestoredProject(storageType: StorageType, storage: StorageService, project: ProjectReference) {
    if (storageType !== 'local') return project
    if (!storage.resolveProject) throw new Error('Local project validation is not available')

    return storage.resolveProject(project)
}

export class ProjectSessionService extends EventTarget {
    private cardCreationState: CardCreationState = { isCreatingCard: false }
    private readonly newCardAttachmentPaths = new Set<string>()
    private readonly newCardAttachmentSaves = new Set<Promise<unknown>>()
    private readonly newCardImageSaves = new Set<Promise<void>>()
    private readonly newCardImagePaths = new Set<string>()
    readonly newCardMarkdownDraft = new MarkdownDraft('')
    private readonly projectAccess = projectAccessService
    private state: ProjectSessionState = {
        errorMessage: null,
        isCommitting: false,
        isLoading: false,
        isPulling: false,
        isPushing: false,
        pendingGithubConflictProject: null,
    }

    constructor() {
        super()
        register('projectSessionService', this)
    }

    getSnapshot(): ProjectSessionState {
        return this.state
    }

    getCardCreationSnapshot(): CardCreationState {
        return this.cardCreationState
    }

    get isReadOnly() {
        return this.projectAccess.getSnapshot()
    }

    hasNewCardDraftImages() {
        return this.hasNewCardDraftAssets()
    }

    hasNewCardDraftAssets() {
        return this.newCardAttachmentPaths.size > 0
            || this.newCardAttachmentSaves.size > 0
            || this.newCardImagePaths.size > 0
            || this.newCardImageSaves.size > 0
    }

    async pasteNewCardImage(file: File, insertMarkdown: (markdown: string) => void) {
        const operation = this.saveAndInsertNewCardImage(file, insertMarkdown)
        this.newCardImageSaves.add(operation)
        try {
            await operation
        } finally {
            this.newCardImageSaves.delete(operation)
        }
    }

    async waitForNewCardImageSaves() {
        await this.waitForNewCardAssetSaves()
    }

    async copyNewCardAttachments(files: File[]) {
        const operation = dataService.cards.copyAttachmentsForNewCard(files)
        this.newCardAttachmentSaves.add(operation)
        try {
            const attachments = await operation
            attachments.forEach(({ path }) => this.newCardAttachmentPaths.add(path))

            return attachments
        } finally {
            this.newCardAttachmentSaves.delete(operation)
        }
    }

    async deleteNewCardDraftAttachments(paths: string[]) {
        for (const path of paths) {
            await dataService.cards.deleteCopiedAttachments([path])
            this.newCardAttachmentPaths.delete(path)
        }
    }

    async waitForNewCardAssetSaves() {
        while (this.newCardAttachmentSaves.size > 0 || this.newCardImageSaves.size > 0) {
            await Promise.allSettled([...this.newCardAttachmentSaves, ...this.newCardImageSaves])
        }
    }

    async discardNewCardDraftImages() {
        await this.discardNewCardDraftAssets()
    }

    async discardNewCardDraftAssets() {
        await this.waitForNewCardAssetSaves()
        let deletionError: unknown = null
        for (const path of [...this.newCardImagePaths]) {
            try {
                await dataService.cards.deletePastedImage(path)
                this.newCardImagePaths.delete(path)
            } catch (error) {
                deletionError ??= error
            }
        }
        for (const path of [...this.newCardAttachmentPaths]) {
            try {
                await dataService.cards.deleteCopiedAttachments([path])
                this.newCardAttachmentPaths.delete(path)
            } catch (error) {
                deletionError ??= error
            }
        }
        if (deletionError) throw deletionError
    }

    setError(message: string | null) {
        this.state = { ...this.state, errorMessage: message, pendingGithubConflictProject: null }
        this.dispatchChanged()
    }

    /** Restore last project through same service-owned loading path used by explicit project opens. */
    async restoreLastProject(accessToken: string | null) {
        this.setError(null)
        const lastProject = readLastProject()
        if (!lastProject) return
        if ((lastProject.storageType === 'github' || lastProject.storageType === 'github-readonly') && !accessToken) return

        const storage = createStorageService(lastProject.storageType, accessToken)
        const project = await resolveRestoredProject(lastProject.storageType, storage, lastProject.project)
        await activateProjectSession(storage, lastProject.storageType, project)
    }

    async listRepositories(accessToken: string | null): Promise<RepositoryReference[]> {
        return this.withLoading('Repository list failed', async () => createGithubStorage(accessToken).listRepositories())
    }

    async listBranches(storageType: StorageType, project: ProjectReference, accessToken: string | null): Promise<BranchReference[]> {
        return this.withLoading('Branch list failed', async () => {
            const storage = createStorageService(storageType, accessToken)

            return storage.listBranches(project)
        })
    }

    async findGithubRepositoryBranches(
        owner: string,
        repositoryName: string,
        accessToken: string | null,
        storageType: 'github' | 'github-readonly' = 'github',
    ) {
        return this.withLoading('Manual repository branch list failed', async () => {
            const storage = createGithubStorage(accessToken, storageType === 'github-readonly')
            const repository = await storage.findRepository(owner, repositoryName)
            const branches = await storage.listBranches(repository)

            return { branches, repository }
        })
    }

    async openProject(
        storageType: StorageType,
        project: ProjectReference,
        accessToken: string | null,
        existingStorage?: StorageService,
    ): Promise<ProjectOpenResolution | null> {
        return this.withLoading('Project load failed', async () => {
            const storage = existingStorage ?? createStorageService(storageType, accessToken)
            if (storageType === 'github' || storageType === 'github-readonly' || storageType === 'local') {
                const projectConfig = await storage.loadProjectConfig(project)
                if (storageType === 'github-readonly' || projectConfig !== null) {
                    return loadProjectSession(
                        storage,
                        storageType,
                        project,
                        () => this.setReadOnly(storageType === 'github-readonly'),
                    )
                }

                this.setReadOnly(false)
                const folders = await listTopLevelFolders(storage, project)

                return { folders, kind: 'project-folder-setup', project, storageType }
            }

            return loadProjectSession(storage, storageType, project, () => this.setReadOnly(false))
        })
    }

    async openWorkingFolder(resolution: MissingWorkingFolderResolution, folder: TopLevelFolderReference, accessToken: string | null) {
        projectAccessService.requireWritable()
        await this.withLoading('Working folder selection failed', async () => {
            const storage = createStorageService(resolution.storageType, accessToken)
            await persistWorkingFolder(storage, resolution.project, folder.path)
            await activateProjectSession(storage, resolution.storageType, resolution.project)
            this.setReadOnly(false)
        })
    }

    async createWorkingFolder(resolution: MissingWorkingFolderResolution, accessToken: string | null) {
        projectAccessService.requireWritable()
        await this.withLoading('Working folder creation failed', async () => {
            const storage = createStorageService(resolution.storageType, accessToken)
            const project = await storage.createProject(resolution.project, resolution.resolvedWorkingFolder)
            await persistWorkingFolder(storage, project, resolution.configuredWorkingFolder)
            await activateProjectSession(storage, resolution.storageType, project)
            this.setReadOnly(false)
        })
    }

    async createProjectFolders(resolution: ProjectFolderSetupResolution, projectFolder: string, accessToken: string | null) {
        projectAccessService.requireWritable()
        await this.withLoading('Project folder creation failed', async () => {
            const storage = createStorageService(resolution.storageType, accessToken)
            const normalizedProjectFolder = requireProjectFolder(projectFolder)
            const projectConfig = {
                ...DEFAULT_PROJECT_CONFIG,
                backgroundShade: createRandomProjectBackgroundShade(),
                projectFolder: normalizedProjectFolder,
            }
            const resolvedConfig = resolveProjectConfigPaths(projectConfig)
            const project = await storage.createProject(resolution.project, resolvedConfig.workingFolder)
            await storage.commit({
                branch: project.branch,
                files: createDefaultActionFiles(resolvedConfig.actionsFolder),
                message: 'Add default MDÂ² actions',
            })
            await storage.saveProjectConfig(project, projectConfig)
            configService.loadProjectConfig(projectConfig)
            await activateProjectSession(storage, resolution.storageType, project)
            this.setReadOnly(false)
        })
    }

    configureRemote(endpoint: string) {
        this.setError(null)
        configureRemoteControlConnection({ endpoint })
    }

    async activateRemoteConnection(storage: StorageService) {
        await this.withLoading('Remote desktop config load failed', async () => {
            await activateStorageService('remote', storage)
        })
    }

    async switchBranch(branch: string) {
        await this.withLoading('Branch switch failed', () => dataService.projectLoading.switchBranch(branch))
    }

    async push() {
        projectAccessService.requireWritable()
        this.state = { ...this.state, isPushing: true }
        this.dispatchChanged()

        try {
            await this.withLoading('Push failed', async () => {
                await projectPersistenceService.flushPendingChanges()
                await dataService.projectLoading.push()
            })
        } finally {
            this.state = { ...this.state, isPushing: false }
            this.dispatchChanged()
        }
    }

    async commit() {
        projectAccessService.requireWritable()
        this.state = { ...this.state, isCommitting: true }
        this.dispatchChanged()

        try {
            await this.withLoading('Commit failed', () => projectPersistenceService.flushPendingChanges())
        } finally {
            this.state = { ...this.state, isCommitting: false }
            this.dispatchChanged()
        }
    }

    async pull() {
        projectAccessService.requireWritable()
        this.state = { ...this.state, isPulling: true }
        this.dispatchChanged()

        try {
            await this.withLoading('Pull failed', () => dataService.projectLoading.pull())
        } finally {
            this.state = { ...this.state, isPulling: false }
            this.dispatchChanged()
        }
    }

    discardGithubPendingCommits(project: ProjectReference, accessToken: string | null) {
        projectAccessService.requireWritable()
        const storage = createGithubStorage(accessToken)
        storage.discardPendingCommits(project)
        this.state = { ...this.state, errorMessage: null, pendingGithubConflictProject: null }
        this.dispatchChanged()
    }

    async getReleaseBranchCandidates() {
        return this.withLoading('Release preparation failed', () => dataService.releases.getReleaseBranchCandidates())
    }

    async completeRelease(releaseName: string, selectedBranchNames: string[]) {
        projectAccessService.requireWritable()
        await this.withLoading('Release completion failed', () => dataService.releases.completeRelease(releaseName, selectedBranchNames))
    }

    async createCard(draft: CardDraft, initialState: string) {
        projectAccessService.requireWritable()
        this.setCardCreationState(true)
        if (this.state.errorMessage !== null) this.setError(null)

        try {
            await this.waitForNewCardImageSaves()
            await dataService.cards.createCard(draft, initialState)
            this.newCardAttachmentPaths.clear()
            this.newCardImagePaths.clear()
        } catch (error) {
            const message = error instanceof Error ? error.message : 'Card creation failed'
            this.state = { ...this.state, errorMessage: message, pendingGithubConflictProject: null }
            this.dispatchChanged()
            if (!isProjectLoadErrorReported(error)) dialogService.error(error, { fallbackMessage: 'Card creation failed' })
            throw error
        } finally {
            this.setCardCreationState(false)
        }
    }

    private setCardCreationState(isCreatingCard: boolean) {
        if (this.cardCreationState.isCreatingCard === isCreatingCard) return

        this.cardCreationState = { isCreatingCard }
        this.dispatchEvent(new CustomEvent<CardCreationState>('cardCreationChanged', { detail: this.cardCreationState }))
    }

    private async saveAndInsertNewCardImage(file: File, insertMarkdown: (markdown: string) => void) {
        const savedImage = await dataService.cards.savePastedImageForNewCard(file)
        this.newCardImagePaths.add(savedImage.path)
        try {
            insertMarkdown(`![pasted image](<${savedImage.fileName}>)`)
        } catch (error) {
            try {
                await dataService.cards.deletePastedImage(savedImage.path)
                this.newCardImagePaths.delete(savedImage.path)
            } catch (cleanupError) {
                dialogService.error(cleanupError, { fallbackMessage: `Could not remove ${savedImage.path}` })
            }
            throw error
        }
    }

    private setReadOnly(isReadOnly: boolean) {
        this.projectAccess.setReadOnly(isReadOnly)
    }

    private async withLoading<T>(fallbackMessage: string, operation: () => Promise<T>): Promise<T> {
        this.state = { ...this.state, errorMessage: null, isLoading: true, pendingGithubConflictProject: null }
        this.dispatchChanged()

        try {
            return await operation()
        } catch (error) {
            const message = error instanceof Error ? error.message : fallbackMessage
            this.state = {
                ...this.state,
                errorMessage: message,
                isLoading: false,
                pendingGithubConflictProject: error instanceof GithubPendingCommitConflictError ? error.project : null,
            }
            this.dispatchChanged()
            if (!isProjectLoadErrorReported(error)) dialogService.error(error, { fallbackMessage })
            throw error
        } finally {
            if (this.state.isLoading) {
                this.state = { ...this.state, isLoading: false }
                this.dispatchChanged()
            }
        }
    }

    private dispatchChanged() {
        this.dispatchEvent(new CustomEvent<ProjectSessionState>('changed', { detail: this.state }))
    }
}

export const projectSessionService = new ProjectSessionService()

import { Button, Menu, MenuItem } from '@mui/material'
import type { MouseEvent } from 'react'
import { useCallback, useState } from 'react'
import { projectSessionService } from '../../services/project/project_session_service'
import { BranchSwitchDialog } from './project/branch_switch_dialog'
import { CompleteReleaseDialog } from './project/complete_release_dialog'
import { NewCardDialog } from './project/new_card_dialog'
import { ProjectOpenDialog } from './project/project_open_dialog'
import { useProjectToolbarMenuActions } from './project/use_project_toolbar_menu_actions'
import { useProjectPersistence } from '../hooks/use_project_persistence'
import { useProjectReadOnly } from '../hooks/use_project_read_only'

type ProjectDialogMode = 'open' | 'branch' | 'card' | 'release'

interface ProjectToolbarMenuProps {
    accessToken: string | null
    isGithubAuthenticated: boolean
}

/** Toolbar project menu with dialogs for project session commands. */
export function ProjectToolbarMenu(props: ProjectToolbarMenuProps) {
    const { accessToken, isGithubAuthenticated } = props
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const [dialogMode, setDialogMode] = useState<ProjectDialogMode | null>(null)
    const { hasPendingPush, hasPendingSave } = useProjectPersistence()
    const readOnly = useProjectReadOnly()
    const isMenuOpen = !!anchorElement

    const openDialog = useCallback((mode: ProjectDialogMode) => {
        setAnchorElement(null)
        setDialogMode(mode)
        projectSessionService.setError(null)
    }, [])

    const handleCloseDialogState = useCallback(() => {
        setDialogMode(null)
    }, [])
    const actions = useProjectToolbarMenuActions({
        accessToken,
        isGithubAuthenticated,
        onCloseDialog: handleCloseDialogState,
        onOpenDialog: openDialog,
    })

    const handleProjectButtonClick = (event: MouseEvent<HTMLButtonElement>) => setAnchorElement(event.currentTarget)
    const handleCloseMenu = () => setAnchorElement(null)
    const handleOpenProject = () => {
        setAnchorElement(null)
        actions.openProjectDialog()
    }
    const handlePushClick = async () => {
        setAnchorElement(null)
        try {
            await actions.push()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }
    const handleOpenReleaseDialog = () => {
        void actions.openReleaseDialog()
    }
    const handleOpenCardDialog = () => actions.openNewCardDialog()
    const handleCreateProjectFolders = (projectFolder: string) => {
        void actions.createProjectFolders(projectFolder)
    }
    const handleDiscardGithubPendingCommits = () => {
        if (!actions.pendingGithubConflictProject) return

        projectSessionService.discardGithubPendingCommits(actions.pendingGithubConflictProject, accessToken)
    }

    return (
        <>
            <Button aria-controls={isMenuOpen ? 'project-menu' : undefined} aria-haspopup="true" onClick={handleProjectButtonClick} size="small" variant="outlined">
                Project
            </Button>
            <Menu anchorEl={anchorElement} id="project-menu" onClose={handleCloseMenu} open={isMenuOpen}>
                <MenuItem onClick={handleOpenProject}>Open project...</MenuItem>
                {actions.isProjectOpen ? <MenuItem onClick={actions.openBranchDialog}>Switch branch...</MenuItem> : null}
                {actions.isProjectOpen && actions.pushMode === 'manual' ? (
                    <MenuItem
                        disabled={readOnly || actions.isLoading || (!hasPendingPush && !hasPendingSave)}
                        onClick={handlePushClick}
                    >
                        Push
                    </MenuItem>
                ) : null}
                {actions.isProjectOpen ? (
                    <MenuItem
                        disabled={readOnly || actions.isReleaseCompleting || actions.activeCards.length === 0}
                        onClick={handleOpenReleaseDialog}
                    >
                        Complete release...
                    </MenuItem>
                ) : null}
                {actions.isProjectOpen ? <MenuItem disabled={readOnly} onClick={handleOpenCardDialog}>New card...</MenuItem> : null}
            </Menu>
            <ProjectOpenDialog
                branches={actions.branches}
                initialRemoteProject={actions.initialRemoteProject}
                initialSource={actions.initialProjectSource}
                isDesktopMode={actions.isDesktopMode}
                isGithubAuthenticated={isGithubAuthenticated}
                isLoading={actions.isLoading}
                onChooseLocalFolder={actions.chooseLocalProjectFolder}
                onCreateProjectFolders={handleCreateProjectFolders}
                projectOpenResolution={actions.projectOpenResolution}
                onBranchChange={() => undefined}
                onClose={actions.closeDialog}
                onCreateRemoteProject={actions.createRemoteProject}
                onCreateWorkingFolder={() => void actions.createWorkingFolder()}
                onDiscardGithubPendingCommits={handleDiscardGithubPendingCommits}
                onLoadManualBranches={actions.loadManualBranches}
                onLoadRemoteBranches={actions.loadRemoteBranches}
                onOpenGithub={actions.openGithubProject}
                onOpenLocal={actions.openLocalProject}
                onOpenRemote={actions.openRemoteProject}
                onRepositoryChange={actions.loadRepositoryBranches}
                onSourceChange={actions.clearOpenDialogState}
                onUseWorkingFolder={(folder) => void actions.openWorkingFolder(folder)}
                open={dialogMode === 'open'}
                pendingGithubConflictProject={actions.pendingGithubConflictProject}
                recentLocalRepositories={actions.recentLocalRepositories}
                repositories={actions.repositories}
            />
            <BranchSwitchDialog
                branches={actions.branches}
                isLoading={actions.isLoading}
                onBranchChange={actions.setSwitchBranch}
                onClose={actions.closeDialog}
                onSwitchBranch={(branch) => void actions.switchProjectBranch(branch)}
                open={dialogMode === 'branch'}
                selectedBranch={actions.switchBranch}
            />
            <CompleteReleaseDialog
                branchCandidates={actions.releaseBranchCandidates}
                defaultSelectAll={actions.releaseSelectAllDefault}
                isLoading={actions.isLoading}
                key={dialogMode === 'release' ? 'release-open' : 'release-closed'}
                onClose={actions.closeDialog}
                onCompleteRelease={actions.completeRelease}
                onSelectAllDefaultChange={actions.setReleaseSelectAllDefault}
                open={dialogMode === 'release'}
            />
            <NewCardDialog
                cardTypes={actions.cardTypes}
                initialTargetStatus={actions.newCardInitialStatus}
                isLoading={actions.isLoading}
                isProjectOpen={actions.isProjectOpen}
                onClose={actions.closeDialog}
                onCreateCard={actions.createCard}
                open={dialogMode === 'card'}
                states={actions.states}
            />
        </>
    )
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import {
    DEFAULT_CARD_TYPES,
    DEFAULT_STATES,
    type BranchReference,
    type CardDraft,
    type ProjectReference,
    type PushMode,
    type ReleaseBranchCandidate,
    type RepositoryReference,
    type TopLevelFolderReference,
} from '../../../data/data_types'
import { getElectronDataBridge } from '../../../data/electron_data_bridge'
import { readRecentLocalRepositories, recordRecentLocalRepository } from '../../../data/recent_local_repositories'
import type { StorageType } from '../../../data/project_session'
import { dialogService } from '../../../services/dialog_service'
import { configService } from '../../../services/config/config_service'
import { projectSessionService, type ProjectOpenResolution } from '../../../services/project/project_session_service'
import { useProjectConfig } from '../../hooks/use_project_config'
import { useConfigValueOrFallback } from '../../hooks/use_config_value'
import { useProjectSession } from '../../hooks/use_project_session'
import { useProjectState } from '../../hooks/use_project_state'
import {
    OPEN_NEW_CARD_DIALOG_EVENT,
    OPEN_PROJECT_DIALOG_EVENT,
    type OpenNewCardDialogDetail,
    type OpenProjectDialogDetail,
    type ProjectDialogSource,
} from '../../project_command_events'

type ProjectDialogMode = 'open' | 'branch' | 'card' | 'release'
type ProjectOpenResult = 'failed' | 'opened' | 'resolution'

const EMPTY_BRANCHES: BranchReference[] = []
const EMPTY_REPOSITORIES: RepositoryReference[] = []

interface UseProjectToolbarMenuActionsArgs {
    accessToken: string | null
    isGithubAuthenticated: boolean
    onCloseDialog: () => void
    onOpenDialog: (mode: ProjectDialogMode) => void
}

function branchExists(branches: BranchReference[], branchName: string) {
    return branches.some(({ name }) => name === branchName)
}

function branchValue(branches: BranchReference[], preferredBranch: string) {
    if (branchExists(branches, preferredBranch)) return preferredBranch

    return branches[0]?.name ?? ''
}

/** Owns project menu service calls and non-dialog session state. */
export function useProjectToolbarMenuActions(args: UseProjectToolbarMenuActionsArgs) {
    const { accessToken, isGithubAuthenticated, onCloseDialog, onOpenDialog } = args
    const { project, snapshot } = useProjectState()
    const projectSession = useProjectSession()
    const projectConfig = useProjectConfig()
    const electronBridge = useMemo(() => getElectronDataBridge(), [])
    const [branches, setBranches] = useState<BranchReference[]>(EMPTY_BRANCHES)
    const [isReleaseCompleting, setIsReleaseCompleting] = useState(false)
    const [projectOpenResolution, setProjectOpenResolution] = useState<ProjectOpenResolution | null>(null)
    const [initialProjectSource, setInitialProjectSource] = useState<ProjectDialogSource | null>(null)
    const [initialRemoteProject, setInitialRemoteProject] = useState<ProjectReference | null>(null)
    const [newCardInitialStatus, setNewCardInitialStatus] = useState('')
    const [pendingLocalRootPath, setPendingLocalRootPath] = useState<string | null>(null)
    const [recentLocalRepositories, setRecentLocalRepositories] = useState(() => readRecentLocalRepositories())
    const [repositories, setRepositories] = useState<RepositoryReference[]>(EMPTY_REPOSITORIES)
    const [releaseBranchCandidates, setReleaseBranchCandidates] = useState<ReleaseBranchCandidate[]>([])
    const [switchBranch, setSwitchBranch] = useState(project?.branch ?? '')
    const activeCards = snapshot?.activeCards ?? []
    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES
    const states = projectConfig?.states ?? DEFAULT_STATES
    const pushMode = (projectConfig?.pushMode ?? 'auto') as PushMode
    const releaseSelectAllDefault = useConfigValueOrFallback('react.deleteBranchesAfterRelease', false)

    const closeDialog = useCallback(() => {
        onCloseDialog()
        setProjectOpenResolution(null)
        projectSessionService.setError(null)
    }, [onCloseDialog])

    const openProject = useCallback(async (storageType: StorageType, nextProject: ProjectReference): Promise<ProjectOpenResult> => {
        setProjectOpenResolution(null)

        try {
            const resolution = await projectSessionService.openProject(storageType, nextProject, accessToken)
            if (resolution) {
                setProjectOpenResolution(resolution)
                onOpenDialog('open')

                return 'resolution'
            }

            closeDialog()
            return 'opened'
        } catch {
            // ProjectSessionService emits the user-visible error.
            return 'failed'
        }
    }, [accessToken, closeDialog, onOpenDialog])

    const recordOpenedLocalProject = useCallback((rootPath: string) => {
        setRecentLocalRepositories(recordRecentLocalRepository(rootPath))
        setPendingLocalRootPath(null)
    }, [])

    const openResolvedLocalProject = useCallback(async (nextProject: ProjectReference) => {
        if (!nextProject.rootPath) throw new Error('Resolved local repository has no root path')

        const result = await openProject('local', nextProject)
        if (result === 'opened') recordOpenedLocalProject(nextProject.rootPath)
        if (result === 'resolution') setPendingLocalRootPath(nextProject.rootPath)
    }, [openProject, recordOpenedLocalProject])

    const chooseLocalProjectFolder = useCallback(async () => {
        if (!electronBridge) return

        let nextProject: ProjectReference | null
        try {
            nextProject = await electronBridge.openProjectFolder()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Local project selection failed' })

            return
        }

        if (nextProject) await openResolvedLocalProject(nextProject)
    }, [electronBridge, openResolvedLocalProject])

    const openLocalProject = useCallback(async (rootPath: string) => {
        if (!electronBridge) return

        const normalizedPath = rootPath.trim()
        if (normalizedPath.length === 0) return

        try {
            const nextProject = await electronBridge.resolveProject({ branch: '', id: normalizedPath, rootPath: normalizedPath })
            await openResolvedLocalProject(nextProject)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Local project selection failed' })
        }
    }, [electronBridge, openResolvedLocalProject])

    const loadRepositories = useCallback(async () => {
        try {
            setRepositories(await projectSessionService.listRepositories(accessToken))
        } catch {
            setRepositories(EMPTY_REPOSITORIES)
        }
    }, [accessToken])

    const loadSwitchBranches = useCallback(async () => {
        if (!project) return

        try {
            const storageType = project.rootPath ? 'local' : 'github'
            const nextBranches = await projectSessionService.listBranches(storageType, project, accessToken)
            setBranches(nextBranches)
            setSwitchBranch(branchValue(nextBranches, project.branch))
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }, [accessToken, project])

    useEffect(() => {
        const handleOpenProjectDialog = (event: Event) => {
            const detail = (event as CustomEvent<OpenProjectDialogDetail>).detail
            setInitialProjectSource(detail?.source ?? null)
            setInitialRemoteProject(detail?.project ?? null)
            setProjectOpenResolution(detail?.resolution ?? null)
            onOpenDialog('open')
            if (isGithubAuthenticated) void loadRepositories()
        }

        window.addEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)

        return () => window.removeEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)
    }, [isGithubAuthenticated, loadRepositories, onOpenDialog])

    useEffect(() => {
        const handleOpenNewCardDialog = (event: Event) => {
            if (!project) return

            const { status } = (event as CustomEvent<OpenNewCardDialogDetail>).detail
            const initialStatus = states.some((stateConfig) => stateConfig.state === status) ? status : states[0]?.state
            setNewCardInitialStatus(initialStatus ?? '')
            onOpenDialog('card')
        }

        window.addEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)

        return () => window.removeEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)
    }, [onOpenDialog, project, states])

    const openNewCardDialog = () => {
        setNewCardInitialStatus(states[0]?.state ?? '')
        onOpenDialog('card')
    }

    const openProjectDialog = () => {
        setInitialProjectSource(null)
        setInitialRemoteProject(null)
        onOpenDialog('open')
        if (isGithubAuthenticated) void loadRepositories()
    }

    const openBranchDialog = () => {
        onOpenDialog('branch')
        void loadSwitchBranches()
    }

    const clearOpenDialogState = () => {
        setBranches(EMPTY_BRANCHES)
        setProjectOpenResolution(null)
    }

    const loadRepositoryBranches = async (repository: RepositoryReference) => {
        try {
            const nextBranches = await projectSessionService.listBranches('github', repository, accessToken)
            setBranches(nextBranches)

            return nextBranches
        } catch {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }
    }

    const loadManualBranches = async (owner: string, repositoryName: string, isPublic: boolean) => {
        try {
            const storageType = isPublic ? 'github-readonly' : 'github'
            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken, storageType)
            setBranches(result.branches)

            return result
        } catch {
            return null
        }
    }

    const createRemoteProject = (rootPath: string, branch: string): ProjectReference | null => {
        try {
            if (rootPath.length === 0) throw new Error('Missing remote project root path')

            return { branch: branch || 'main', id: rootPath, rootPath }
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Remote project could not be created' })

            return null
        }
    }

    const loadRemoteBranches = async (endpoint: string, rootPath: string, branch: string) => {
        const remoteProject = createRemoteProject(rootPath, branch)
        if (!remoteProject) {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }

        projectSessionService.configureRemote(endpoint)

        try {
            const nextBranches = await projectSessionService.listBranches('remote', remoteProject, accessToken)
            setBranches(nextBranches)

            return nextBranches
        } catch {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }
    }

    const openGithubProject = async (owner: string, repositoryName: string, branch: string, isPublic: boolean) => {
        try {
            const storageType = isPublic ? 'github-readonly' : 'github'
            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken, storageType)
            const fallbackBranches = branches.length > 0 ? branches : result.branches
            const selectedBranch = branch || branchValue(fallbackBranches, result.repository.branch)
            setBranches(fallbackBranches)
            await openProject(storageType, { ...result.repository, branch: selectedBranch })
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const openRemoteProject = async (endpoint: string, nextProject: ProjectReference) => {
        projectSessionService.configureRemote(endpoint)
        await openProject('remote', nextProject)
    }

    const openWorkingFolder = async (folder: TopLevelFolderReference) => {
        if (projectOpenResolution?.kind !== 'missing-working-folder') return

        try {
            await projectSessionService.openWorkingFolder(projectOpenResolution, folder, accessToken)
            if (pendingLocalRootPath) recordOpenedLocalProject(pendingLocalRootPath)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const createWorkingFolder = async () => {
        if (projectOpenResolution?.kind !== 'missing-working-folder') return

        try {
            await projectSessionService.createWorkingFolder(projectOpenResolution, accessToken)
            if (pendingLocalRootPath) recordOpenedLocalProject(pendingLocalRootPath)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const createProjectFolders = async (projectFolder: string) => {
        if (projectOpenResolution?.kind !== 'project-folder-setup') return

        try {
            await projectSessionService.createProjectFolders(projectOpenResolution, projectFolder, accessToken)
            if (pendingLocalRootPath) recordOpenedLocalProject(pendingLocalRootPath)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

